class ResourceHolder {
    int* data;
    size_t count;

    ResourceHolder(size_t c) : count(c), data(new int[c]) {}

    // 1. Destructor (Delete owned resource)
    ~ResourceHolder() { delete[] data; }

    // 2. Copy Constructor (Deep copy required)
    ResourceHolder(const ResourceHolder& other)
      : count(other.count), data(new int[other.count]) {
        for (size_t i = 0; i < count; ++i) data[i] = other.data[i];
    }

    // 3. Copy Assignment (Handle self-assignment, reallocate)
    ResourceHolder& operator=(const ResourceHolder& other) {
        if (this == &other) return *this;
        delete[] data;
        count = other.count;
        data = new int[count];
        for (size_t i = 0; i < count; ++i) data[i] = other.data[i];
        return *this;
    }
};
